// Groq'tan gelen response'u al
const response = $input.first().json;

let content;

// Groq formatı: choices[0].message.content
if (response.choices && response.choices[0]) {
  content = response.choices[0].message.content;
} else if (response.content) {
  content = response.content;
} else {
  return [{
    json: {
      error: "Unexpected response format",
      raw_response: response
    }
  }];
}

// JSON'u parse et (markdown temizle)
let cleanContent = content;

if (cleanContent.includes('```')) {
  cleanContent = cleanContent.replace(/```json\n?/g, '').replace(/```\n?/g, '');
}

cleanContent = cleanContent.trim();

try {
  const scriptData = JSON.parse(cleanContent);

  const scenes = scriptData.scenes.map(scene => ({
    json: {
      title: scriptData.title,
      total_duration: scriptData.total_duration || 20,
      scene_number: scene.scene_number,
      narration: scene.narration || "",
      word_count: scene.word_count || 0,
      video_prompt: scene.video_prompt,
      sound_effect: scene.sound_effect || "",
      is_climax: scene.is_climax || false
    }
  }));

  return scenes;

} catch (e) {
  return [{
    json: {
      error: "JSON parse failed: " + e.message,
      raw_content: cleanContent
    }
  }];
}

const items = $input.all();

const output = {
  title: items[0].json.title,
  total_duration: items[0].json.total_duration,
  generated_at: new Date().toISOString(),
  scenes: items.map(item => ({
    scene_number: item.json.scene_number,
    narration: item.json.narration,
    word_count: item.json.word_count,
    video_prompt: item.json.video_prompt,
    sound_effect: item.json.sound_effect,
    is_climax: item.json.is_climax
  })),
  all_prompts: items.map(item => item.json.video_prompt).join('\n\n---\n\n'),
  all_narrations: items.filter(item => item.json.narration).map(item => item.json.narration).join('\n')
};

return [{ json: output }];

