const data = $input.first().json;

const narrations = data.scenes
  .filter(scene => scene.narration && scene.narration.length > 0)
  .map(scene => ({
    json: {
      scene_number: scene.scene_number,
      narration: scene.narration,
      word_count: scene.word_count
    }
  }));

return narrations;

const inputData = $input.all();
const firstItem = inputData[0].json;

let scenes = [];

if (firstItem.scenes) {
  scenes = firstItem.scenes;
} else if (Array.isArray(firstItem)) {
  scenes = firstItem[0]?.scenes || firstItem;
}

const videoPrompts = scenes.map((scene, index) => ({
  json: {
    scene_number: scene.scene_number,
    video_prompt: scene.video_prompt,
    duration: 5,
    is_climax: scene.is_climax || false,
    sound_effect: scene.sound_effect || "",
    aspect_ratio: "9:16"
  }
}));

return videoPrompts;

