const speeches = $('Convert text to speech1').all();
const videos = $('Get_Kling_Video').all();

const videoCount = videos.length;
const audioCount = speeches.length;

const elements = [];
let currentTime = 0;

for (let i = 0; i < videoCount; i++) {
  const videoUrl = videos[i].json.data?.output?.video_url || videos[i].json.output?.video_url || '';

  if (i < audioCount) {
    const audioUrl = speeches[i].json.url || speeches[i].json.data?.url || '';

    elements.push({
      "id": `video-${i + 1}`,
      "type": "video",
      "track": 1,
      "time": currentTime,
      "duration": null,
      "source": videoUrl,
      "loop": true,
      "fit": "cover",
      "volume": "0%"
    });

    elements.push({
      "id": `audio-${i + 1}`,
      "type": "audio",
      "track": 2,
      "time": currentTime,
      "duration": null,
      "source": audioUrl,
      "volume": "100%"
    });

    currentTime = `{{ ${elements[elements.length - 1].id}.duration }}`;

  } else {
    elements.push({
      "id": `video-${i + 1}`,
      "type": "video",
      "track": 1,
      "time": currentTime,
      "duration": 5,
      "source": videoUrl,
      "fit": "cover",
      "volume": "100%"
    });
  }
}

const creatomateBody = {
  "output_format": "mp4",
  "width": 1080,
  "height": 1920,
  "elements": elements
};

return {
  json: creatomateBody
};

